referenceSolutions.javascript:
export function medianOfTwoSortedArrays(left          , right          )         {
const a         =[];let i=0,j=0;while(i<left.length||j<right.length){if(j===right.length||(i<left.length&&left[i]<=right[j]))a.push(left[i++]);else a.push(right[j++]);}const n=a.length;return n%2?2*a[n>>1]:a[n/2-1]+a[n/2];
}

